--
-- Create function `hoopStress`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS hoopStress (idSample int UNSIGNED, pressure int)
RETURNS int(11)
DETERMINISTIC
BEGIN

  SET @hoopResult = 0;

  SELECT
    (((pressure * (s.diamreal - s.wallthick)) / (10 * 2 * s.wallthick))) INTO @hoopResult
  FROM sample s
  WHERE s.id = idSample;

  RETURN @hoopResult;
END
$$

