--
-- Create function `selectTestNumber`
--
CREATE
DEFINER = 'root'@'%'
FUNCTION IF NOT EXISTS selectTestNumber (idSpecimen int UNSIGNED)
RETURNS int(11) UNSIGNED
DETERMINISTIC
BEGIN
  SET @testNumber = 0;

  SET @sampleID = (SELECT
      ts.sample
    FROM specimen ts
    WHERE ts.id = idSpecimen);

  SELECT
    COUNT(*) INTO @testNumber
  FROM specimen ts
  WHERE ts.id <= idSpecimen
  AND ts.sample = @sampleID
  GROUP BY ts.sample;

  RETURN @testNumber;
END
$$

--
-- Create function `countSpecimens`
--
CREATE
DEFINER = 'root'@'%'
FUNCTION IF NOT EXISTS countSpecimens (standardIN text, materialIN text, specificationIN text, diameterNominalIN int UNSIGNED, diameterRealIN int UNSIGNED, wallthicknessIN int UNSIGNED, lengthFreeIN int UNSIGNED, lengthTotalIN int UNSIGNED)
RETURNS int(11) UNSIGNED
DETERMINISTIC
BEGIN
  SET @count = 0;

  WITH mySample (ID)
  AS
  (SELECT
      s.id AS ID
    FROM sample s
    WHERE s.standard LIKE standardIN
    AND s.material LIKE materialIN
    AND s.specification LIKE specificationIN
    AND s.diamnom = diameterNominalIN
    AND s.diamreal = diameterRealIN
    AND s.wallthick = wallthicknessIN
    AND s.lenfree = lengthFreeIN
    AND s.lentotal = lengthTotalIN)

  SELECT
    COUNT(*) INTO @count
  FROM specimen ts
  WHERE ts.sample = (SELECT
      ms.ID
    FROM mySample ms)
  GROUP BY ts.sample;

  RETURN @count;
END
$$

