--
-- Create function `selectTestLimit`
--
CREATE
DEFINER = 'root'@'%'
FUNCTION IF NOT EXISTS selectTestLimit (idSpecimen int UNSIGNED, isASC tinyint UNSIGNED)
RETURNS datetime
DETERMINISTIC
BEGIN

  SET @Time = NULL;

  IF isASC = 0 THEN
    SELECT
      td.createdAt INTO @Time
    FROM data td
    WHERE td.specimen = idSpecimen
    ORDER BY td.createdAt ASC LIMIT 1;
  ELSE
    SELECT
      td.createdAt INTO @Time
    FROM data td
    WHERE td.specimen = idSpecimen
    ORDER BY td.createdAt DESC LIMIT 1;
  END IF;

  RETURN @Time;
END
$$

--
-- Create function `selectTestsSpecimens`
--
CREATE
DEFINER = 'root'@'%'
FUNCTION IF NOT EXISTS selectTestsSpecimens (idSample int UNSIGNED)
RETURNS json
DETERMINISTIC
BEGIN
  SET @myResult = NULL;

  WITH preResults
  AS
  (SELECT
      ts.id,
      ts.targetPressure,
      ts.targetTemperature,
      ts.operator,
      selectTestNumber(ts.id) AS testNumber,
      (selectTestLimit(ts.id, 0)) AS beginTime,
      (selectTestLimit(ts.id, 1)) AS endTime
    FROM specimen ts
    WHERE ts.sample = idSample)

  (SELECT
      JSON_ARRAYAGG(JSON_OBJECT('idSpecimen', pr.id,
      'testNumber', ROW_NUMBER() OVER (
      ORDER BY pr.id),
      'targetPressure', pr.targetPressure,
      'targetTemperature', pr.targetTemperature,
      'operator', pr.operator,
      'testNumber', pr.testNumber,
      'beginTime', DATE_FORMAT(pr.beginTime, '%d/%m/%Y %H:%i:%s'),
      'endTime', DATE_FORMAT(pr.endTime, '%d/%m/%Y %H:%i:%s'),
      'duration', DATE_FORMAT(TIMEDIFF(pr.endTime, pr.beginTime), '%H:%i:%s'))) INTO @myResult
    FROM preResults pr
    ORDER BY pr.id DESC);

  RETURN @myResult;
END
$$

--
-- Create procedure `selectTest`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS selectTest (IN idSpecimenIN int UNSIGNED)
DETERMINISTIC
BEGIN

  SET @countSpecimens = (SELECT
      COUNT(*)
    FROM specimen spe
    WHERE spe.id = idSpecimenIN
    GROUP BY spe.sample);
  SET @beginTime = DATE_FORMAT((SELECT
      MIN(d.createdAt)
    FROM data d
    WHERE d.specimen = idSpecimenIN), '%d/%m/%Y %H:%i:%s');
  SET @endTime = DATE_FORMAT((SELECT
      MAX(d.createdAt)
    FROM data d
    WHERE d.specimen = idSpecimenIN), '%d/%m/%Y %H:%i:%s');
  SET @timeDiff = DATE_FORMAT(TIMEDIFF(@endTime, @beginTime), '%H:%i:%s');

  SELECT
    s.id AS idSpecimen,
    s.sample AS idSample,
    s1.standard AS standard,
    s1.material AS material,
    s1.specification AS specification,
    s1.diamreal AS diameterReal,
    s1.diamnom AS diameterNominal,
    s1.wallthick AS wallThickness,
    s1.lenfree AS lengthFree,
    s1.lentotal AS lengthTotal,
    s1.condPeriod AS conditionalPeriod,
    @countSpecimens AS specimensCount,
    (IF(s.targetPressure IS NULL, NULL, s.targetPressure)) AS targetPressure,
    (IF(s.targetTemperature IS NULL, NULL, s.targetTemperature)) AS targetTemperature,
    s.operator AS operator,
    s.enviroment AS enviroment,
    s.testName AS testName,
    s.endCap AS endCap,
    s.failText AS failText,
    s.remark AS remark,
    @beginTime AS beginTime,
    @endTime AS endTime,
    @timeDiff AS duration
  FROM specimen s
    INNER JOIN sample s1
      ON s.sample = s1.id
  WHERE s.id = idSpecimenIN;

END
$$

--
-- Create procedure `selectData`
--
CREATE
DEFINER = 'root'@'%'
PROCEDURE IF NOT EXISTS selectData (IN idSpecimenIN int UNSIGNED, IN intervalIN int UNSIGNED, IN timeTypeIN char(1))
DETERMINISTIC
BEGIN

  SET @initTime = (SELECT
      td.createdAt
    FROM data td
    WHERE td.specimen = idSpecimenIN
    ORDER BY td.createdAt ASC LIMIT 1);

  IF (intervalIN = 1
    AND timeTypeIN LIKE 's') THEN
    WITH subTable (id, pressure, temperature, ambient, createdAt)
    AS
    (SELECT
        ROW_NUMBER() OVER (
        ORDER BY TIMESTAMPDIFF(SECOND, @initTime, d.createdAt)) AS id,
        d.pressure AS pressure,
        d.temperature AS temperature,
        d.ambient AS ambient,
        d.createdAt
      FROM data d
      WHERE d.specimen = idSpecimenIN)
    SELECT
      st.id,
      IF(timeTypeIN LIKE 'h', CAST(st.id / 360 AS UNSIGNED), IF(timeTypeIN LIKE 'm', CAST(st.id / 6 AS UNSIGNED), CAST(st.id AS UNSIGNED))) AS `key`,
      st.pressure,
      st.temperature,
      st.ambient,
      st.createdAt
    FROM subTable st;
  ELSE
    WITH subTable (id, pressure, temperature, ambient, createdAt)
    AS
    (SELECT
        ROW_NUMBER() OVER (
        ORDER BY TIMESTAMPDIFF(SECOND, @initTime, d.createdAt)) AS id,
        d.pressure AS pressure,
        d.temperature AS temperature,
        d.ambient AS ambient,
        d.createdAt
      FROM data d
      WHERE d.specimen = idSpecimenIN)

    SELECT
      st.id,
      IF(timeTypeIN LIKE 'h', CAST(st.id / 360 AS UNSIGNED), IF(timeTypeIN LIKE 'm', CAST(st.id / 6 AS UNSIGNED), CAST(st.id AS UNSIGNED))) AS `key`,
      st.pressure,
      st.temperature,
      st.ambient,
      st.createdAt
    FROM subTable st
    WHERE st.id % intervalIN = 1;
  END IF;
END
$$

DELIMITER ;

